# Single request; no automatic mutation replay. Set TOKEN, REPORT_ID, ARTIFACT in the process environment. Save/resume returned IDs; use the downloadable workflow client for polling, staged uploads and recovery.
import os, json, pathlib, tempfile, urllib.request, urllib.parse, uuid
def env(name):
    value = os.environ.get(name)
    if not value: raise ValueError('Set '+name)
    return value
class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *args, **kwargs): return None
url = "https://dwsoffshorepartners.com/api/v1/reports/" + urllib.parse.quote(env('REPORT_ID'), safe='') + "/artifacts/" + urllib.parse.quote(env('ARTIFACT'), safe='') + ""
headers = {'Authorization': 'Bearer '+env('TOKEN'), 'Accept': 'application/json, application/octet-stream', 'Accept-Encoding': 'identity'}
data = None
request = urllib.request.Request(url, data=data, headers=headers, method='GET')
try:
    with urllib.request.build_opener(NoRedirect).open(request, timeout=120) as response:
        output = pathlib.Path(tempfile.mkdtemp(prefix='ultiwrite-response-', dir='.'))/'response.bin'
        expected = response.headers.get('Content-Length')
        if expected is not None and not expected.isdigit(): raise OSError('Invalid response length')
        count = 0
        try:
            with output.open('xb') as target:
                os.chmod(output, 0o600)
                while chunk := response.read(65536):
                    target.write(chunk)
                    count += len(chunk)
            if expected is not None and count != int(expected): raise OSError('Incomplete response')
        except BaseException:
            output.unlink(missing_ok=True)
            raise
        print('Saved response in '+str(output))
except urllib.error.HTTPError as error:
    raise SystemExit('HTTP '+str(error.code)) from None

// Single request; no automatic mutation replay. Set TOKEN, REPORT_ID, ARTIFACT in the process environment. Save/resume returned IDs; use the downloadable workflow client for polling, staged uploads and recovery.
// Java17+, no third-party dependencies for this single request.
import java.net.*;
import java.net.http.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.io.*;
public class RequestExample {
  static String env(String name) { String v=System.getenv(name); if(v==null||v.isEmpty()) throw new IllegalArgumentException("Set "+name); return v; }
  static String segment(String value) { return URLEncoder.encode(value,StandardCharsets.UTF_8).replace("+","%20"); }
  public static void main(String[] args) throws Exception {
    String url = "https://dwsoffshorepartners.com/api/v1/reports/" + segment(env("REPORT_ID")) + "/artifacts/" + segment(env("ARTIFACT")) + "";
    var request = HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(120))
      .header("Authorization","Bearer "+env("TOKEN")).header("Accept","application/json, application/octet-stream");
    request.method("GET",HttpRequest.BodyPublishers.noBody());
    var client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(15)).followRedirects(HttpClient.Redirect.NEVER).build();
    var response=client.send(request.build(),HttpResponse.BodyHandlers.ofInputStream());
    try(var body=response.body()) {
      if(response.statusCode()<200||response.statusCode()>=300) throw new IOException("HTTP "+response.statusCode());
      var directory=Files.createTempDirectory(Path.of("."),"ultiwrite-response-");
      var output=directory.resolve("response.bin");
      try { Files.copy(body,output); } catch(Exception error) { Files.deleteIfExists(output); throw error; }
      System.out.println("Saved response in "+output);
    }
  }
}

