using System.Net.Http.Headers;
static string Env(string name) => Environment.GetEnvironmentVariable(name) is { Length: > 0 } value ? value : throw new Exception("Set "+name);
using var handler = new HttpClientHandler { AllowAutoRedirect = false };
using var client = new HttpClient(handler) { Timeout = TimeSpan.FromSeconds(120) };
using var request = new HttpRequestMessage(new HttpMethod("GET"), "https://dwsoffshorepartners.com/api/v1/reports/" + Uri.EscapeDataString(Env("REPORT_ID")) + "/artifacts/" + Uri.EscapeDataString(Env("ARTIFACT")) + "");
request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", Env("TOKEN"));
request.Headers.Accept.ParseAdd("application/json, application/octet-stream");

using var response = await client.SendAsync(request,HttpCompletionOption.ResponseHeadersRead);
if (!response.IsSuccessStatusCode) throw new Exception("HTTP "+(int)response.StatusCode);
var directory=Directory.CreateTempSubdirectory("ultiwrite-response-");
var output=Path.Combine(directory.FullName,"response.bin");
try {
  using var target=new FileStream(output,FileMode.CreateNew,FileAccess.Write,FileShare.None);
  await response.Content.CopyToAsync(target);
} catch { File.Delete(output); throw; }
Console.WriteLine("Saved response in "+output);

