package main
import ("fmt"; "io"; "net/http"; "net/url"; "os"; "strings"; "time")
var _ = url.PathEscape
var _ = strings.NewReader
func env(name string) string { v:=os.Getenv(name); if v=="" { panic("Set "+name) }; return v }
func run() error {
  endpoint := "https://dwsoffshorepartners.com/api/v1/reports/" + url.PathEscape(env("REPORT_ID")) + "/artifacts/" + url.PathEscape(env("ARTIFACT")) + ""
  var body io.Reader
  contentType := ""

  request,err:=http.NewRequest("GET",endpoint,body); if err!=nil{return err}
  request.GetBody=nil
  if request.Method!="GET" && request.Method!="HEAD" && (request.Body==nil || request.Body==http.NoBody) {request.Body=io.NopCloser(strings.NewReader(""));request.ContentLength=-1}
  request.Header.Set("Authorization","Bearer "+env("TOKEN")); request.Header.Set("Accept","application/json, application/octet-stream")
  if contentType!="" { request.Header.Set("Content-Type",contentType) }
  client:=&http.Client{Timeout:120*time.Second,CheckRedirect:func(_ *http.Request,_ []*http.Request)error{return http.ErrUseLastResponse}}
  response,err:=client.Do(request); if err!=nil{return err}; defer response.Body.Close()
  if response.StatusCode<200||response.StatusCode>=300{return fmt.Errorf("HTTP %d",response.StatusCode)}
  dir,err:=os.MkdirTemp(".","ultiwrite-response-");if err!=nil{return err}
  target,err:=os.OpenFile(dir+"/response.bin",os.O_CREATE|os.O_EXCL|os.O_WRONLY,0600);if err!=nil{return err};defer target.Close()
  if _,err=io.Copy(target,response.Body);err!=nil{target.Close();os.Remove(dir+"/response.bin");return err};fmt.Println("Saved response in "+dir+"/response.bin");return nil
}
func main(){if err:=run();err!=nil{message:="Request failed; inspect status and request ID privately";if strings.HasPrefix(err.Error(),"HTTP "){message=err.Error()};fmt.Fprintln(os.Stderr,message);os.Exit(1)}}

